# -*- coding: utf-8 -*-
from rn_p1 import T, X
from rn_p2 import ex, EX, s1, s2, s3, s4, IND0, IND0C, INDINF, LIM, SIM, SOL, aligned

CONJ_SQ = r"\sqrt[3]{(%s)^{2}}"
# =============================================================== RAVEN
ex("rn-raven-01", "m", *LIM, r"\lim_{x \to 2} \frac{\sqrt[3]{3x + 2} - 2}{x - 2}",
   [s1("2"), X(r"\frac{\sqrt[3]{3 \times 2 + 2} - 2}{2 - 2} = \frac{\sqrt[3]{8} - 2}{0} = \frac{2 - 2}{0} = \frac{0}{0}"), IND0C,
    s2(r"\sqrt[3]{3x+2}", "2", "a^{2} + 2a + 4"),
    X(r"\frac{\sqrt[3]{3x+2} - 2}{x - 2} = \frac{(3x + 2) - 8}{(x - 2)\left(a^{2} + 2a + 4\right)}"),
    s3(r" : $(3x + 2) - 8 = 3x - 6 = 3(x - 2)$", r": $(3x + 2) - 8 = 3x - 6 = 3(x - 2)$"),
    X(r"\frac{3(x - 2)}{(x - 2)\left(a^{2} + 2a + 4\right)} = \frac{3}{a^{2} + 2a + 4}"),
    s4("2"), X(r"\lim_{x \to 2} \frac{\sqrt[3]{3x + 2} - 2}{x - 2} = \frac{3}{4 + 4 + 4} = \frac{3}{12} = \frac{1}{4}")])
ex("rn-raven-02", "m", *LIM, r"\lim_{x \to 0} \frac{\sqrt[3]{1 + 2x} - \sqrt[3]{1 - x}}{x}",
   [s1("0"), X(r"\frac{\sqrt[3]{1} - \sqrt[3]{1}}{0} = \frac{1 - 1}{0} = \frac{0}{0}"), IND0C,
    T(r"**Étape 2.** On pose $a = \sqrt[3]{1 + 2x}$ et $b = \sqrt[3]{1 - x}$. Le conjugué est $a^{2} + ab + b^{2}$. On calcule :", r"**Step 2.** Let $a = \sqrt[3]{1 + 2x}$ and $b = \sqrt[3]{1 - x}$. The conjugate is $a^{2} + ab + b^{2}$. We compute:"),
    X(r"a^{3} - b^{3} = (1 + 2x) - (1 - x) = 3x"),
    s3(),
    X(r"\frac{a - b}{x} = \frac{a^{3} - b^{3}}{x\,(a^{2} + ab + b^{2})} = \frac{3x}{x\,(a^{2} + ab + b^{2})} = \frac{3}{a^{2} + ab + b^{2}}"),
    T(r"**Étape 4.** Quand $x \to 0$, $a \to 1$ et $b \to 1$ :", r"**Step 4.** When $x \to 0$, $a \to 1$ and $b \to 1$:"),
    X(r"\lim_{x \to 0} \frac{\sqrt[3]{1 + 2x} - \sqrt[3]{1 - x}}{x} = \frac{3}{1 + 1 + 1} = 1")])
ex("rn-raven-03", "m", *LIM, r"\lim_{x \to 1} \frac{\sqrt[3]{x + 7} - \sqrt[3]{3x + 5}}{x - 1}",
   [s1("1"), X(r"\frac{\sqrt[3]{8} - \sqrt[3]{8}}{0} = \frac{2 - 2}{0} = \frac{0}{0}"), IND0C,
    T(r"**Étape 2.** On pose $a = \sqrt[3]{x + 7}$ et $b = \sqrt[3]{3x + 5}$. Le conjugué est $a^{2} + ab + b^{2}$. On calcule :", r"**Step 2.** Let $a = \sqrt[3]{x + 7}$ and $b = \sqrt[3]{3x + 5}$. The conjugate is $a^{2} + ab + b^{2}$. We compute:"),
    X(r"a^{3} - b^{3} = (x + 7) - (3x + 5) = 2 - 2x = -2(x - 1)"),
    s3(r" : le facteur $x - 1$ disparaît", r": the factor $x - 1$ cancels"),
    X(r"\frac{-2(x - 1)}{(x - 1)\,(a^{2} + ab + b^{2})} = \frac{-2}{a^{2} + ab + b^{2}}"),
    T(r"**Étape 4.** Quand $x \to 1$, $a \to 2$ et $b \to 2$ :", r"**Step 4.** When $x \to 1$, $a \to 2$ and $b \to 2$:"),
    X(r"\lim_{x \to 1} \frac{\sqrt[3]{x + 7} - \sqrt[3]{3x + 5}}{x - 1} = \frac{-2}{4 + 4 + 4} = -\frac{1}{6}")])
ex("rn-raven-04", "m", *LIM, r"\lim_{x \to +\infty} \left(\sqrt[3]{x^{3} + 2x^{2}} - x\right)",
   [s1(r"+\infty"), X(r"+\infty - \infty"), INDINF,
    s2(r"\sqrt[3]{x^{3}+2x^{2}}", "x", "a^{2} + ax + x^{2}"),
    X(r"a - x = \frac{a^{3} - x^{3}}{a^{2} + ax + x^{2}} = \frac{2x^{2}}{a^{2} + ax + x^{2}}"),
    T(r"**Étape 3.** On écrit $a = x\left(1 + \frac{2}{x}\right)^{1/3}$ et on divise en haut et en bas par $x^{2}$ :", r"**Step 3.** Write $a = x\left(1 + \frac{2}{x}\right)^{1/3}$ and divide top and bottom by $x^{2}$:"),
    X(r"a - x = \frac{2}{\left(1 + \frac{2}{x}\right)^{2/3} + \left(1 + \frac{2}{x}\right)^{1/3} + 1}"),
    T(r"**Étape 4.** Quand $x \to +\infty$, $\frac{2}{x} \to 0$ :", r"**Step 4.** When $x \to +\infty$, $\frac{2}{x} \to 0$:"),
    X(r"\lim_{x \to +\infty} \left(\sqrt[3]{x^{3} + 2x^{2}} - x\right) = \frac{2}{1 + 1 + 1} = \frac{2}{3}")])
ex("rn-raven-05", "m", *LIM, r"\lim_{x \to -\infty} \left(\sqrt[3]{x^{3} + x^{2} + 1} - x\right)",
   [s1(r"-\infty"), X(r"-\infty - (-\infty) = -\infty + \infty"), INDINF,
    s2(r"\sqrt[3]{x^{3}+x^{2}+1}", "x", "a^{2} + ax + x^{2}"),
    X(r"a - x = \frac{a^{3} - x^{3}}{a^{2} + ax + x^{2}} = \frac{x^{2} + 1}{a^{2} + ax + x^{2}}"),
    T(r"**Étape 3.** On pose $u = 1 + \frac{1}{x} + \frac{1}{x^{3}}$, donc $a = x\,u^{1/3}$. C’est valable en $-\infty$ car $\sqrt[3]{x^{3}} = x$ (indice impair, pas de valeur absolue). On divise en haut et en bas par $x^{2}$ :",
      r"**Step 3.** Let $u = 1 + \frac{1}{x} + \frac{1}{x^{3}}$, so $a = x\,u^{1/3}$. This is valid at $-\infty$ since $\sqrt[3]{x^{3}} = x$ (odd index, no absolute value). Divide top and bottom by $x^{2}$:"),
    X(r"a - x = \frac{1 + \frac{1}{x^{2}}}{u^{2/3} + u^{1/3} + 1}"),
    T(r"**Étape 4.** Quand $x \to -\infty$, $u \to 1$ et $\frac{1}{x^{2}} \to 0$ :", r"**Step 4.** When $x \to -\infty$, $u \to 1$ and $\frac{1}{x^{2}} \to 0$:"),
    X(r"\lim_{x \to -\infty} \left(\sqrt[3]{x^{3} + x^{2} + 1} - x\right) = \frac{1}{1 + 1 + 1} = \frac{1}{3}")])
ex("rn-raven-06", "m", *LIM, r"\lim_{x \to +\infty} \left(\sqrt[3]{x^{3} + x^{2}} - \sqrt[3]{x^{3} - x^{2}}\right)",
   [s1(r"+\infty"), X(r"+\infty - \infty"), INDINF,
    T(r"**Étape 2.** On pose $a = \sqrt[3]{x^{3} + x^{2}}$ et $b = \sqrt[3]{x^{3} - x^{2}}$. Le conjugué est $a^{2} + ab + b^{2}$. On calcule :", r"**Step 2.** Let $a = \sqrt[3]{x^{3} + x^{2}}$ and $b = \sqrt[3]{x^{3} - x^{2}}$. The conjugate is $a^{2} + ab + b^{2}$. We compute:"),
    X(r"a^{3} - b^{3} = 2x^{2} \qquad\Longrightarrow\qquad a - b = \frac{2x^{2}}{a^{2} + ab + b^{2}}"),
    T(r"**Étape 3.** On écrit $a = x\,u^{1/3}$ et $b = x\,v^{1/3}$ avec $u = 1 + \frac{1}{x}$ et $v = 1 - \frac{1}{x}$, puis on divise en haut et en bas par $x^{2}$ :",
      r"**Step 3.** Write $a = x\,u^{1/3}$ and $b = x\,v^{1/3}$ with $u = 1 + \frac{1}{x}$ and $v = 1 - \frac{1}{x}$, then divide top and bottom by $x^{2}$:"),
    X(r"a - b = \frac{2}{u^{2/3} + (uv)^{1/3} + v^{2/3}}"),
    T(r"**Étape 4.** Quand $x \to +\infty$, $u \to 1$ et $v \to 1$ :", r"**Step 4.** When $x \to +\infty$, $u \to 1$ and $v \to 1$:"),
    X(r"\lim_{x \to +\infty} \left(\sqrt[3]{x^{3} + x^{2}} - \sqrt[3]{x^{3} - x^{2}}\right) = \frac{2}{1 + 1 + 1} = \frac{2}{3}")])
ex("rn-raven-07", "m", *LIM, r"\lim_{x \to 0} \frac{\sqrt[3]{1 + x} - 1}{\sqrt[3]{1 + 2x} - 1}",
   [s1("0"), X(r"\frac{\sqrt[3]{1} - 1}{\sqrt[3]{1} - 1} = \frac{0}{0}"), IND0,
    T(r"**Étape 2.** On pose $a = \sqrt[3]{1 + x}$ et $c = \sqrt[3]{1 + 2x}$. On multiplie chaque différence par son conjugué cubique :", r"**Step 2.** Let $a = \sqrt[3]{1 + x}$ and $c = \sqrt[3]{1 + 2x}$. Multiply each difference by its cubic conjugate:"),
    X(r"a - 1 = \frac{a^{3} - 1}{a^{2} + a + 1} = \frac{x}{a^{2} + a + 1}"),
    X(r"c - 1 = \frac{c^{3} - 1}{c^{2} + c + 1} = \frac{2x}{c^{2} + c + 1}"),
    s3(r" le quotient (le facteur $x$ disparaît)", r" the quotient (the factor $x$ cancels)"),
    X(r"\frac{a - 1}{c - 1} = \frac{x}{a^{2} + a + 1} \times \frac{c^{2} + c + 1}{2x} = \frac{c^{2} + c + 1}{2\,(a^{2} + a + 1)}"),
    T(r"**Étape 4.** Quand $x \to 0$, $a \to 1$ et $c \to 1$ :", r"**Step 4.** When $x \to 0$, $a \to 1$ and $c \to 1$:"),
    X(r"\lim_{x \to 0} \frac{\sqrt[3]{1 + x} - 1}{\sqrt[3]{1 + 2x} - 1} = \frac{3}{2 \times 3} = \frac{1}{2}")])
ex("rn-raven-08", "m", *LIM, r"\lim_{x \to -8} \frac{\sqrt[3]{x} + 2}{x + 8}",
   [s1("-8"), X(r"\frac{\sqrt[3]{-8} + 2}{-8 + 8} = \frac{-2 + 2}{0} = \frac{0}{0}"), IND0,
    T(r"**Étape 2.** On pose $a = \sqrt[3]{x}$. Alors $x + 8 = a^{3} + 8$, et on utilise l’identité de $a^{3} + b^{3}$ :", r"**Step 2.** Let $a = \sqrt[3]{x}$. Then $x + 8 = a^{3} + 8$, and we use the identity for $a^{3} + b^{3}$:"),
    X(r"x + 8 = a^{3} + 2^{3} = (a + 2)(a^{2} - 2a + 4)"),
    s3(r" par $a + 2$", r" by $a + 2$"),
    X(r"\frac{a + 2}{(a + 2)(a^{2} - 2a + 4)} = \frac{1}{a^{2} - 2a + 4}"),
    T(r"**Étape 4.** Quand $x \to -8$, $a \to -2$, donc $a^{2} \to 4$ et $-2a \to 4$ :", r"**Step 4.** When $x \to -8$, $a \to -2$, so $a^{2} \to 4$ and $-2a \to 4$:"),
    X(r"\lim_{x \to -8} \frac{\sqrt[3]{x} + 2}{x + 8} = \frac{1}{4 + 4 + 4} = \frac{1}{12}")])
ex("rn-raven-09", "m", r"Résoudre dans $\mathbb{R}$ (pour $E_{3}$, poser $t = \sqrt[3]{x}$) :", r"Solve in $\mathbb{R}$ (for $E_{3}$, let $t = \sqrt[3]{x}$):",
   aligned([r"E_{1} &: \sqrt[3]{x^{2} + 2x - 1} = \sqrt[3]{2x + 3}", r"E_{2} &: \sqrt{x + 2} = x", r"E_{3} &: \sqrt[3]{x^{2}} - 3\sqrt[3]{x} + 2 = 0"]),
   [T(r"**$E_{1}$ :** les deux côtés existent toujours (indice $3$). On élève au cube :", r"**$E_{1}$:** both sides always exist (index $3$). Raise to the cube:"),
    X(r"x^{2} + 2x - 1 = 2x + 3 \iff x^{2} = 4"),
    X(r"S = \{-2,\ 2\}"),
    T(r"**$E_{2}$ :** conditions : $x + 2 \ge 0$ et $x \ge 0$ (une racine carrée est positive). On élève au carré :", r"**$E_{2}$:** conditions: $x + 2 \ge 0$ and $x \ge 0$ (a square root is positive). Square both sides:"),
    X(r"x + 2 = x^{2} \iff x^{2} - x - 2 = 0 \iff (x - 2)(x + 1) = 0"),
    T(r"$x = 2$ convient : $\sqrt{4} = 2$ ✓.", r"$x = 2$ works: $\sqrt{4} = 2$ ✓."),
    T(r"$x = -1$ est rejeté : $\sqrt{1} = 1 \neq -1$.", r"$x = -1$ is rejected: $\sqrt{1} = 1 \neq -1$."),
    X(r"S = \{2\}"),
    T(r"**$E_{3}$ :** on pose $t = \sqrt[3]{x}$, donc $\sqrt[3]{x^{2}} = t^{2}$ :", r"**$E_{3}$:** let $t = \sqrt[3]{x}$, so $\sqrt[3]{x^{2}} = t^{2}$:"),
    X(r"t^{2} - 3t + 2 = 0 \iff (t - 1)(t - 2) = 0"),
    X(r"t = 1 \qquad ;\qquad t = 2"),
    T(r"Alors $x = t^{3}$ :", r"Then $x = t^{3}$:"),
    X(r"x = 1 \qquad ;\qquad x = 8"),
    T(r"Vérification : $x = 8$ donne $4 - 6 + 2 = 0$ ✓ et $x = 1$ donne $1 - 3 + 2 = 0$ ✓.", r"Check: $x = 8$ gives $4 - 6 + 2 = 0$ ✓ and $x = 1$ gives $1 - 3 + 2 = 0$ ✓."),
    X(r"S = \{1,\ 8\}")])
ex("rn-raven-10", "m", *SIM, r"A = \sqrt[3]{54} + \sqrt[3]{250} - \sqrt[3]{16}",
   [T(r"On décompose chaque nombre pour faire apparaître un cube :", r"Decompose each number to make a cube appear:"),
    X(r"\sqrt[3]{54} = \sqrt[3]{27 \times 2} = 3\sqrt[3]{2}"),
    X(r"\sqrt[3]{250} = \sqrt[3]{125 \times 2} = 5\sqrt[3]{2}"),
    X(r"\sqrt[3]{16} = \sqrt[3]{8 \times 2} = 2\sqrt[3]{2}"),
    T(r"On factorise $\sqrt[3]{2}$ :", r"Factor out $\sqrt[3]{2}$:"),
    X(r"A = (3 + 5 - 2)\sqrt[3]{2} = 6\sqrt[3]{2}")])
ex("rn-raven-11", "m", r"Simplifier $a$, $b$ et $c$, puis les ranger par ordre croissant :", r"Simplify $a$, $b$ and $c$, then order them from smallest to largest:",
   aligned([r"a &= \sqrt{3} \times \sqrt[4]{3}", r"b &= \sqrt[6]{81}", r"c &= \sqrt[3]{3} \times \sqrt[4]{3}"]),
   [T(r"**Simplification.** On passe en puissances de $3$ (avec $81 = 3^{4}$) :", r"**Simplification.** Switch to powers of $3$ (with $81 = 3^{4}$):"),
    X(r"a = 3^{1/2} \times 3^{1/4} = 3^{3/4}"),
    X(r"b = \sqrt[6]{3^{4}} = 3^{4/6} = 3^{2/3}"),
    X(r"c = 3^{1/3} \times 3^{1/4} = 3^{7/12}"),
    T(r"**Comparaison.** On met les exposants au même dénominateur $12$ :", r"**Comparison.** Put the exponents over the same denominator $12$:"),
    X(r"a = 3^{9/12}, \qquad b = 3^{8/12}, \qquad c = 3^{7/12}"),
    T(r"Comme $3 > 1$, la puissance croît avec l’exposant, et $7 < 8 < 9$ :", r"Since $3 > 1$, the power increases with the exponent, and $7 < 8 < 9$:"),
    X(r"c < b < a")])
